begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
select ok((select rolcanlogin and not rolsuper and not rolbypassrls and not rolinherit and not rolcreaterole and not rolcreatedb from pg_roles where rolname='redondeado_api'), 'runtime login has restricted attributes');
select ok((select not rolcanlogin and not rolsuper and not rolbypassrls from pg_roles where rolname='redondeado_public'), 'public operation role cannot log in or bypass RLS');
select ok(pg_has_role('redondeado_api', 'authenticated', 'member') and pg_has_role('redondeado_api', 'redondeado_public', 'member'), 'runtime can assume only fixed application roles');
select ok(not pg_has_role('redondeado_api', 'service_role', 'member'), 'runtime cannot assume service role');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p','v','m') and c.relowner=(select oid from pg_roles where rolname='redondeado_api')), 0::bigint, 'runtime owns no application relations');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join (values ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) x(priv) where n.nspname='public' and c.relkind in ('r','p') and has_table_privilege('redondeado_public', c.oid, x.priv)), 0::bigint, 'public role has no broad application table privileges');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not (coalesce(p.proconfig, '{}') @> array['search_path=""'])), 0::bigint, 'all application security definer functions have empty search paths');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl, acldefault('f',p.proowner))) a where n.nspname in ('public','private') and p.prosecdef and a.grantee=0 and a.privilege_type='EXECUTE'), 0::bigint, 'no application security definer function is executable by PUBLIC');
select ok(has_function_privilege('redondeado_public', 'public.book_public_appointment(text,uuid,uuid,timestamptz,text,text,text,uuid[])', 'execute'), 'public booking role can invoke booking');
select ok(not has_function_privilege('redondeado_public', 'public.manage_booking_terms(uuid,uuid,text)', 'execute') and not has_function_privilege('authenticated', 'public.book_public_appointment(text,uuid,uuid,timestamptz,text,text,text,uuid[])', 'execute'), 'public and staff operations have separate execute grants');
select * from finish();
rollback;
